// Topic-specific dialogue revisions. Shared by lesson pages and every conversation player.
const revisions = {};
function add(id, focus, rows) {
 revisions[id] = {focus, lines:rows.map(([en,zh],i)=>({speaker:i%2?'Ben':'Maya',en,zh,note:focus}))};
}
export const UNIT_DIALOGUE_REVISIONS = revisions;
export function applyUnitDialogueRevisions(grades) {
 for(const g of grades)for(const s of g.semesters)for(const u of s.units){
  const r=revisions[u.id]; if(r){u.dialogue=r.lines.map(l=>({...l}));u.dialogueFocus=r.focus;}
 }
}
add("g3-s1-u2","字母名稱與音值不同；聽完整單字 sun、zebra，不讓合成語音朗讀斜線音標。",[["What letter is this?", "這是什麼字母？"], ["It's S. Can you find a word that starts with S?", "是 S。你找得到 S 開頭的單字嗎？"], ["Sun! What about this letter?", "Sun！那這個字母呢？"], ["It's Z, like the Z in zebra.", "是 Z，就像 zebra 裡的 Z。"]]);
add("g4-s1-u1","拼讀練習先聽完整單字，再念字母名稱；文字朗讀不是孤立音素示範。",[["Can you read this word: hat?", "你會讀 hat 這個字嗎？"], ["Hat! Is that your hat?", "Hat！那是你的帽子嗎？"], ["Yes, it is. Now spell dog.", "是。現在拼出 dog。"], ["D, O, G. I can read dog, too!", "D、O、G。我也會讀 dog！"]]);
add("g4-s1-u2","釐清數字時用數位重述 one five；thirteen、thirty 的重音會受句子強調影響。",[["This toy car is fifteen dollars.", "這台玩具車十五元。"], ["Did you say fifteen or fifty?", "你說十五還是五十？"], ["Fifteen. That's one five.", "十五，就是一、五。"], ["OK. Here's twenty dollars.", "好，給你二十元。"]]);
add("g4-s1-u3","服務情境可用 Can I get 或 I'd like 禮貌點餐。",[["Good morning! What can I get for you?", "早安！你想點什麼？"], ["I'd like a sandwich and some milk, please.", "我想要一份三明治和一些牛奶，謝謝。"], ["Would you like an egg, too?", "也要一顆蛋嗎？"], ["No, thanks. That's all.", "不用，謝謝。這樣就好。"]]);
add("g5-s1-u1","不發音 e 是常見拼字模式而非通則；以 cape、cap 對照，不把字典音標交給一般文字朗讀。",[["How do you say this word: cape?", "cape 這個字怎麼念？"], ["Cape. The e is silent in this word.", "Cape。這個字的 e 不發音。"], ["And without the e, it's cap, right?", "拿掉 e 就是 cap，對嗎？"], ["Right! A cap goes on your head. A cape goes over your shoulders.", "對！Cap 戴在頭上，cape 披在肩上。"]]);
add("g6-s1-u4","描述症狀與詢問照護，不用簡短對話直接診斷或指定劑量。",[["I don't feel well. My throat hurts.", "我不舒服，喉嚨痛。"], ["I'm sorry to hear that. Have you told the school nurse?", "聽起來真不好受。你告訴校護了嗎？"], ["Not yet. Could you walk there with me?", "還沒。你可以陪我走過去嗎？"], ["Of course. Let's ask the nurse what to do next.", "當然。我們問問校護接下來怎麼辦。"]]);
add("g6-s2-u5","用 What do you do 與 We usually 描述節慶習慣，避免把同一文化說成人人相同。",[["Do you celebrate Thanksgiving with your family?", "你和家人會過感恩節嗎？"], ["Yes. We usually have dinner together. What about your family?", "會。我們通常一起吃晚餐。你們家呢？"], ["We celebrate the Mid-Autumn Festival. We eat mooncakes.", "我們過中秋節，會吃月餅。"], ["That sounds fun. I'd love to try one.", "聽起來很好玩。我很想試吃一個。"]]);
add("g6-s2-u6","用字首 un- 推測 unknown，再以句子上下文確認，不只背中文字義。",[["This story says the island was unknown. What does unknown mean?", "故事說這座島是 unknown。Unknown 是什麼意思？"], ["Known means people know it. Un- makes it the opposite.", "Known 表示人們知道，un- 讓意思相反。"], ["So nobody knew about the island yet?", "所以當時還沒有人知道這座島？"], ["Right. Let's read the next sentence to check.", "對。我們讀下一句確認一下。"]]);
add("g6-s2-u7","be going to 描述計畫；want to 描述志向，兩者不等同必然實現。",[["What are you going to do this summer?", "今年暑假你打算做什麼？"], ["I'm going to help at an animal shelter.", "我打算去動物收容所幫忙。"], ["Really? Do you want to work with animals someday?", "真的嗎？你以後想從事和動物有關的工作嗎？"], ["Yes. I want to be a vet when I grow up.", "想。我長大想當獸醫。"]]);
add("g6-s2-u8","比較兩者用比較級；比較群體中的最高程度用最高級。",[["Which backpack is lighter, the blue one or the green one?", "藍色和綠色背包哪個比較輕？"], ["The blue one is lighter, but the green one is bigger.", "藍色比較輕，不過綠色比較大。"], ["What about the black one?", "那黑色的呢？"], ["It's the biggest of the three. I can fit all my books in it.", "它是三個裡面最大的，我所有書都放得下。"]]);
add("g7-s1-u2","指示代名詞配合單複數；祈使句用動詞原形提出指示。",[["Are these your notebooks?", "這些是你的筆記本嗎？"], ["Yes, they are. That red folder is mine, too.", "對，那個紅色資料夾也是我的。"], ["Please put them on this shelf.", "請把它們放在這個架子上。"], ["Sure. Is that box for pencils?", "好。那個盒子是放鉛筆的嗎？"]]);
add("g7-s1-u3","查字典時分開檢查重音、音標與例句；音標供閱讀，示範聲音以單字播放。",[["How do you pronounce photographer?", "Photographer 怎麼念？"], ["Let's listen to the dictionary recording.", "我們聽聽字典錄音。"], ["I hear the stress on the second syllable.", "我聽到重音在第二音節。"], ["Me too. Now let's check an example sentence.", "我也是。現在看看例句吧。"]]);
add("g7-s2-u4","現在進行式描述正在發生的動作；完整保留 be 動詞。",[["Why are you carrying all those chairs?", "你怎麼搬著那麼多椅子？"], ["We're setting up for the school concert.", "我們正在為學校音樂會布置。"], ["Is Emma helping with the lights?", "Emma 正在幫忙弄燈光嗎？"], ["Yes, she is. Could you hold the door for me?", "對。可以幫我扶住門嗎？"]]);
add("g7-s2-u5","頻率副詞通常放一般動詞前；there is/are 介紹存在，can 表能力或可行性。",[["How often do you practice guitar?", "你多久練一次吉他？"], ["I usually practice after school. There's a music room upstairs.", "我通常放學後練。樓上有間音樂教室。"], ["Can I practice there with you?", "我可以跟你一起在那裡練嗎？"], ["Sure! There are two spare guitars.", "當然！那裡有兩把備用吉他。"]]);
add("g7-s2-u6","位置用 next to、across from；路線用 turn、go past，並以地標確認。",[["Is the post office next to the bank?", "郵局在銀行旁邊嗎？"], ["No, it's across from the bank, behind the bus stop.", "不是，它在銀行對面、公車站後方。"], ["Should I turn right at the next corner?", "我應該在下個轉角右轉嗎？"], ["Yes. Go past the bakery, and you'll see it on your left.", "對。經過麵包店後，你會看到它在左邊。"]]);
add("g8-s1-u2","過去進行式交代背景；過去簡單式描述插入事件；a few 配可數名詞。",[["What were you doing when the lights went out?", "停電時你在做什麼？"], ["I was making dinner. I only had a few vegetables left to cut.", "我正在做晚餐，只剩幾樣蔬菜還沒切。"], ["Did you finish cooking?", "你後來煮完了嗎？"], ["Yes. While I was looking for a flashlight, the power came back on.", "有。我找手電筒時，電就恢復了。"]]);
add("g8-s1-u3","真實未來條件用 if/unless 加現在式；主句可用 will。",[["Will we still have the picnic if it rains?", "如果下雨，我們還要野餐嗎？"], ["If it rains, we'll eat in the community center.", "下雨的話，我們就在活動中心吃。"], ["Should I bring an umbrella anyway?", "那我還是帶把傘嗎？"], ["Yes. Unless the forecast changes, we'll probably need one.", "對。除非預報改變，不然我們大概用得上。"]]);
add("g8-s2-u4","enjoy 後用動名詞；plan 後用不定詞；比較級用於比較選項。",[["Do you enjoy hiking, or do you prefer cycling?", "你喜歡健行，還是比較喜歡騎腳踏車？"], ["I enjoy cycling. It's easier on my knees.", "我喜歡騎腳踏車，膝蓋比較不吃力。"], ["I'm planning to try the riverside trail this weekend.", "我計畫週末去試試河濱步道。"], ["Great! It's flatter than the mountain route. Can I join you?", "太好了！它比山路平。我可以一起去嗎？"]]);
add("g8-s2-u5","look、smell 可接形容詞描述感官；最高級的比較範圍需清楚。",[["This soup smells amazing. Did you make it?", "這湯聞起來好香，是你煮的嗎？"], ["Yes. It's the easiest recipe in my cookbook.", "對，它是我食譜裡最簡單的一道。"], ["The vegetables look fresh, too.", "蔬菜看起來也很新鮮。"], ["Thanks! Try a little and tell me how it tastes.", "謝謝！嚐一點，告訴我味道怎麼樣。"]]);
add("g9-s1-u1","現在完成式連結目前狀態；被動句描述公告動作；關係子句修飾名詞。",[["Have you seen the bike that was left outside the library?", "你有看到被留在圖書館外的那台腳踏車嗎？"], ["Yes. A notice has been posted on the school website.", "有。學校網站已經貼了公告。"], ["Do they know who owns it?", "他們知道車主是誰嗎？"], ["Not yet. The student who found it is checking with the office.", "還不知道。找到它的學生正在詢問辦公室。"]]);
add("g9-s1-u2","give someone something 為授予句；have someone do 為安排；have done 是完成式。",[["Has Ms. Lee given you the permission form yet?", "李老師已經給你同意書了嗎？"], ["Yes. She gave me an extra copy for my brother.", "給了。她多給我一份讓我帶給弟弟。"], ["Did she have you collect the forms from our class?", "她有請你收我們班的表格嗎？"], ["Yes. I've collected twelve so far.", "有。目前我已經收了十二份。"]]);
add("g9-s1-u3","受格關係代名詞常可省略；介系詞置於句尾是自然口語用法。",[["Is this the book you told me about?", "這就是你之前跟我提過的書嗎？"], ["Yes. The author I spoke to at the fair signed it.", "對。我在書展交談的那位作者還簽了名。"], ["Who did you go with?", "你跟誰一起去的？"], ["My cousin. She's the person I borrowed the first copy from.", "我表姊。我最早就是跟她借這本書。"]]);
add("g9-s2-u4","間接問句使用陳述語序；附加問句的語調取決於確認意圖。",[["The museum closes at five, doesn't it?", "博物館五點關門，對吧？"], ["I think so, but I'm not sure whether the gift shop closes earlier.", "我想是，不過不確定禮品店會不會更早關。"], ["Could you tell me where the information desk is?", "可以告訴我服務台在哪裡嗎？"], ["It's by the entrance. Let's ask there.", "在入口旁。我們去那裡問。"]]);
add("g9-s2-u5","代名詞指涉要回看前文；依據原文而非只看最近名詞猜測。",[["The notice says, 'Leave it at the front desk.' What does it refer to?", "通知寫「把它留在櫃檯」，it 指什麼？"], ["Look at the sentence before it. It mentions the room key.", "看前一句，裡面提到房間鑰匙。"], ["So we return the key, but keep the receipt?", "所以我們交回鑰匙，保留收據？"], ["Exactly. The last sentence says to keep the receipt for our records.", "對。最後一句說收據留作紀錄。"]]);
add("g9-s2-u6","先核對圖表的單位與日期，再將數據連回文字的敘述範圍。",[["The article says more students take the bus, but this chart looks different.", "文章說更多學生搭公車，但這張圖看起來不一樣。"], ["Check the dates. The chart shows last year, and the article describes this year.", "看看日期。圖表是去年，文章說的是今年。"], ["Oh, and the chart uses percentages, not student counts.", "喔，而且圖表用的是百分比，不是學生人數。"], ["Right. Let's compare the same year and the same unit before we answer.", "對。作答前先比較同一年和同一單位。"]]);
add("g10-s1-u1","動詞決定句型：give 可接受兩個受詞；feel 後的形容詞描述主詞。",[["You look tired. Did the presentation go OK?", "你看起來很累，簡報還順利嗎？"], ["Yes. Our teacher gave us some helpful feedback.", "順利。老師給了我們一些有用的回饋。"], ["Did it make you feel more confident?", "那有讓你更有信心嗎？"], ["Definitely. We explained the idea clearly, and everyone understood.", "當然。我們把概念解釋清楚，大家都懂了。"]]);
add("g10-s1-u2","remember to do 是記得要做；remember doing 是記得做過，不可互換。",[["Did you remember to send the application?", "你記得寄出申請了嗎？"], ["I remember filling it out, but I don't remember clicking Send.", "我記得填好了，卻不記得有按寄出。"], ["Let's check your sent folder before you submit it again.", "再送一次前，先看寄件備份吧。"], ["Good idea. I need to stop rushing through online forms.", "好主意。我得改掉匆忙填表的習慣。"]]);
add("g10-s1-u3","被動語態聚焦受影響的對象；公告或數據也可作主詞提供資訊。",[["The notice says the lab is being renovated. Where will our class meet?", "公告說實驗室正在整修，我們要去哪裡上課？"], ["We've been moved to Room 305 for the next two weeks.", "未來兩週改到三〇五教室。"], ["Will the equipment be moved there, too?", "設備也會搬過去嗎？"], ["Only the laptops. The larger machines will stay in storage.", "只有筆電，大型機器會留在儲藏室。"]]);
add("g10-s1-u4","間接問句保留主詞在動詞前；whether 引導是否，不加疑問倒裝。",[["Do you know when the interview starts?", "你知道面試什麼時候開始嗎？"], ["The email says it starts at ten, but I'm not sure which room we're in.", "信上說十點，不過我不確定是哪間教室。"], ["Could you ask whether we need to bring a printed resume?", "可以問問是否要帶紙本履歷嗎？"], ["Sure. I'll also check who we should contact when we arrive.", "可以。我也會確認到了要找誰。"]]);
add("g10-s1-u5","關係子句修飾特定人物或物品；依子句缺口選 who、which 或 that。",[["Who's the student who designed this poster?", "設計這張海報的學生是誰？"], ["That's Nina. She's the one who runs the art club.", "是 Nina，她就是負責美術社的人。"], ["I like the colors that she chose.", "我喜歡她選的顏色。"], ["Me too. The message is easy to read from across the room.", "我也是。從教室另一端也能輕鬆讀到標語。"]]);
add("g10-s1-u6","because、although、so that 分別引導原因、讓步與目的，不只是形式代換。",[["Why are we starting the cleanup so early?", "為什麼淨灘這麼早就開始？"], ["Because it gets hot by noon. We'll finish before the sun is too strong.", "因為中午會很熱，我們要在陽光太強前結束。"], ["Although I'm not a morning person, I'll be there.", "雖然我不太習慣早起，還是會去。"], ["Thanks. Bring a reusable bottle so that you can refill it at the station.", "謝謝。帶可重複使用的水瓶，就能在補給站裝水。"]]);
add("g10-s2-u7","限定子句識別是哪個對象；非限定子句補充資訊，逗號影響句意。",[["Do you mean your cousin who lives in Seattle?", "你是說住在西雅圖的那位表親嗎？"], ["Yes. I have three cousins, so that detail helps identify her.", "對。我有三個表親，那個細節能說清楚是哪一位。"], ["My cousin, who lives in Boston, is visiting next month.", "我的表姊住在波士頓，下個月要來。"], ["So you're adding a detail about the cousin we already know.", "所以你是在補充我們已經知道的那位表姊的資訊。"]]);
add("g10-s2-u8","whoever 指任何符合條件的人；what 可表示所需的事物，不另接先行詞。",[["Who should we give the extra tickets to?", "多出來的票要給誰？"], ["Whoever signs up first can have them.", "先報名的人就可以拿。"], ["And what should people bring to the workshop?", "那參加工作坊的人要帶什麼？"], ["They can bring whatever they need for their own project.", "帶自己作品需要的東西就可以。"]]);
add("g10-s2-u9","however 表轉折，for example 舉例，therefore 表結論；需核對前後實際邏輯。",[["This paragraph starts with however. What's the contrast?", "這段以 however 開頭，轉折在哪裡？"], ["The first paragraph lists the benefits. This one explains the costs.", "第一段列出好處，這段說明成本。"], ["Then for example introduces the parking fees?", "接著 for example 是引出停車費的例子嗎？"], ["Exactly. Each connector tells us how the next idea relates to the last one.", "沒錯。每個連接語都說明新舊想法如何相關。"]]);
add("g10-s2-u10","圖表相關性不等於因果；跨文比較須核對樣本、年份與測量方式。",[["This graph shows longer screen time and lower test scores. Does one cause the other?", "這張圖顯示螢幕時間越長，成績越低。一個會造成另一個嗎？"], ["Not necessarily. The graph only shows a relationship.", "不一定。圖表只顯示關聯。"], ["The second article mentions sleep and study habits, too.", "第二篇文章還提到睡眠和讀書習慣。"], ["Right. Those could affect both variables. We need more evidence.", "對。那些可能同時影響兩個變項，我們需要更多證據。"]]);
add("g10-s2-u11","must、might、can't 可表推測；推測強度需與可觀察證據一致。",[["The classroom is empty. They must have canceled the meeting.", "教室空空的，他們一定取消會議了。"], ["They might have moved it. There's a note on the door.", "也可能是換地方了，門上有張字條。"], ["You're right. It says Room 402.", "你說得對，上面寫四〇二教室。"], ["So the meeting can't be here. Let's go upstairs.", "所以會議不在這裡，我們上樓吧。"]]);
add("g10-s2-u12","綜合練習先辨任務與證據，再用句型表達結論，不靠關鍵字猜答案。",[["Which sentence best summarizes the article?", "哪一句最能概括這篇文章？"], ["I'd choose B. It includes both the problem and the proposed solution.", "我選 B，它包含問題和提出的解法。"], ["What makes C less suitable?", "為什麼 C 比較不適合？"], ["It only describes one example. The whole article covers a broader issue.", "它只描述一個例子，整篇文章討論的議題更廣。"]]);
add("g11-s1-u1","分詞片語的隱含主詞通常與主句一致；bored 與 boring 的描述對象不同。",[["Walking into the hall, I noticed everyone staring at the screen.", "我走進大廳時，發現大家都盯著螢幕。"], ["Was the presentation interesting?", "簡報很有趣嗎？"], ["Yes, but I was confused by the first chart.", "很有趣，不過第一張圖讓我有點困惑。"], ["I felt the same way. The speaker explained it later, though.", "我也一樣，不過講者後來有解釋。"]]);
add("g11-s1-u2","獨立分詞結構可帶不同主詞；口語通常使用完整子句，依語境選擇。",[["The report says, 'Weather permitting, we'll launch on Friday.' What does that mean?", "報告說「Weather permitting, we'll launch on Friday」，是什麼意思？"], ["It means we'll launch if the weather allows it.", "就是天氣允許的話，週五發射。"], ["So weather is the subject of permitting?", "所以 permitting 的主詞是 weather？"], ["Right. In conversation, I'd usually just say, 'If the weather's good.'", "對。一般聊天我通常直接說「如果天氣好」。"]]);
add("g11-s1-u3","與過去事實相反用 had done、would have done；現在假設用過去式形式。",[["If you'd left earlier, would you have caught the train?", "如果你早一點出門，會趕上那班車嗎？"], ["Probably. If I'd caught it, I would have arrived before the interview.", "應該會。如果趕上，我就能在面試前抵達。"], ["What would you do differently next time?", "下次你會怎麼調整？"], ["I'd allow an extra hour in case there's a delay.", "我會多留一小時，以防延誤。"]]);
add("g11-s1-u4","Had I known 省略 if 並倒裝；混合假設可將過去條件連到現在結果。",[["Had I known the course was online, I wouldn't have booked a hotel.", "如果早知道課程在線上，我就不會訂旅館。"], ["Can you still cancel the reservation?", "現在還能取消訂房嗎？"], ["Yes. If I'd chosen the prepaid rate, I'd be out of luck now.", "能。如果當時選預付價，現在就沒辦法了。"], ["I'm glad you checked before the cancellation deadline.", "還好你在取消期限前確認了。"]]);
add("g11-s1-u5","否定副詞前置是強調或正式語體；一般口語常保留通常語序。",[["The speaker said, 'Never have we faced a challenge like this.'", "講者說「Never have we faced a challenge like this」。"], ["That's stronger than saying, 'We've never faced a challenge like this.'", "比直接說「我們從沒面對過這種挑戰」更有強調感。"], ["Would you use that word order in a text to a friend?", "傳訊息給朋友時，你會用那種語序嗎？"], ["Probably not. I'd save it for a speech or formal writing.", "大概不會。我會留在演講或正式寫作使用。"]]);
add("g11-s1-u6","So do I 表同樣肯定，Neither do I 表同樣否定；助動詞需呼應前句。",[["I didn't expect the workshop to be so useful.", "我沒想到工作坊這麼有用。"], ["Neither did I. I learned a lot about giving feedback.", "我也沒想到。我學到很多給回饋的方法。"], ["I want to try those ideas with our project group.", "我想把那些方法用在專題小組。"], ["So do I. Let's start at our next meeting.", "我也想。我們下次開會就開始吧。"]]);
add("g11-s2-u7","分裂句聚焦特定資訊；what 子句可把要強調的事放在句尾。",[["Was it the price that made you change your mind?", "是價格讓你改變心意嗎？"], ["No. It was the delivery time that worried me.", "不是。讓我擔心的是交貨時間。"], ["So what you need is a supplier who can ship this week?", "所以你需要的是本週能出貨的供應商？"], ["Exactly. A lower price won't help if we miss the deadline.", "沒錯。錯過期限的話，再便宜也沒用。"]]);
add("g11-s2-u8","even though 與 even if 分別表事實讓步與假設讓步；正式倒裝依語域使用。",[["Even though the pilot was expensive, the results look promising.", "雖然試辦成本很高，結果看來很有希望。"], ["True, but even if we get more funding, we still need trained staff.", "沒錯，但即使拿到更多經費，還是需要受過訓練的人員。"], ["Should we mention both points in the proposal?", "提案要把兩點都寫進去嗎？"], ["Yes. We should explain the benefit without hiding the limits.", "要。我們應該說明好處，也清楚交代限制。"]]);
add("g11-s2-u9","研究數據需核對測試集與使用情境；準確率不代表模型在所有情境同樣可靠。",[["This AI model reports ninety-five percent accuracy. Is that enough for our project?", "這個 AI 模型報告準確率百分之九十五，夠我們專題用嗎？"], ["We need to know what data it was tested on.", "我們得先知道它用什麼資料測試。"], ["The paper says the test images all came from one hospital.", "論文說測試影像全來自同一家醫院。"], ["Then we should check whether it works on data from other hospitals, too.", "那我們也該確認它在其他醫院資料上是否有效。"]]);
add("g11-s2-u10","永續論證需比較成本、效益與限制；避免把再生能源描述為完全零影響。",[["Should our school put solar panels on the gym roof?", "學校該在體育館屋頂裝太陽能板嗎？"], ["It could reduce our electricity bills, but we need a cost estimate.", "可能降低電費，但需要成本估算。"], ["We should also check how much shade the nearby trees create.", "也該看看附近樹木造成多少遮蔭。"], ["Agreed. Let's compare the expected output with the installation and maintenance costs.", "同意。我們比較預期發電量和安裝、維護成本。"]]);
add("g11-s2-u11","篇章填空先找指涉與論述功能；不把某個單字固定判成正面或負面。",[["Where should this sentence about the survey's limitations go?", "這句談調查限制的句子該放哪裡？"], ["After the results, before the author gives a recommendation.", "放在結果之後、作者提出建議之前。"], ["Because readers need to understand how certain the findings are?", "因為讀者需要先知道研究結果有多確定？"], ["Exactly. It also explains why the recommendation is cautious.", "對，也能解釋為什麼建議比較謹慎。"]]);
add("g11-s2-u12","訂正要區分字詞、語法與推論問題；以可指出的證據修正答案。",[["I got the answer right, but I guessed. Should I still review it?", "我答對了，可是用猜的，還要複習嗎？"], ["Yes. Can you explain which sentence supports your choice?", "要。你能解釋哪句話支持你的選擇嗎？"], ["Not yet. I confused the author's view with the example.", "還不能。我把作者觀點和例子混在一起了。"], ["Let's separate those first, then try a new question.", "先分清楚，再做一道新題。"]]);
add("g12-s1-u1","詞彙選擇要同時符合句法、搭配與上下文，不只比對單一中文字義。",[["Both words mean change. Why doesn't replace fit here?", "兩個字都有改變的意思，為什麼這裡不能用 replace？"], ["The sentence says the company wants to improve the existing system.", "句子說公司想改善現有系統。"], ["So upgrade fits because they're keeping the system?", "所以因為保留系統，用 upgrade 比較合適？"], ["Right. Replace would mean using something else instead.", "對。Replace 會表示改用別的東西。"]]);
add("g12-s1-u2","文意選填先觀察詞性，再追蹤語意；不要只看空格相鄰兩個字。",[["This blank comes after an adjective. Do we need a noun?", "這格在形容詞後面，是不是要填名詞？"], ["Probably, but let's read the whole sentence before we decide.", "可能，不過先讀完整句再決定。"], ["It describes a result of the new policy, so improvement makes sense.", "它在描述新政策的結果，所以 improvement 合理。"], ["Yes. Now check whether the following sentence supports that meaning.", "對。再看下一句有沒有支持這個意思。"]]);
add("g12-s1-u3","長文閱讀先辨主張與證據；混合題簡答避免把例子擴大為整體結論。",[["The question asks why the author mentions the old bridge.", "題目問作者為什麼提到那座舊橋。"], ["It's an example of a repair that cost less than replacement.", "它是修復比重建便宜的一個例子。"], ["So the author isn't saying every old bridge should be kept?", "所以作者不是說所有舊橋都應保留？"], ["Exactly. We should describe the example's role without making the claim broader.", "沒錯。說清楚例子的作用，不要擴大主張。"]]);
add("g12-s1-u4","看圖寫作先描述可觀察細節；論證需加入理由，避免憑圖杜撰人物動機。",[["What can we actually see in the picture?", "圖片裡我們確實看得到什麼？"], ["Two students are sharing an umbrella at a bus stop.", "兩個學生在公車站共撐一把傘。"], ["Should we say they're best friends?", "要說他們是最好的朋友嗎？"], ["We don't know that. Let's describe the action, then explain what it suggests.", "我們不知道。先描述動作，再解釋它可能傳達什麼。"]]);
add("g12-s1-u5","專業文本先找流程順序與條件；技術摘要用自己的話保留核心資訊。",[["The manual says to inspect the cable before connecting the power.", "說明書說接電前要檢查電纜。"], ["So inspection comes first, even if the machine was working yesterday?", "所以就算昨天機器正常，也要先檢查？"], ["Yes. How would you summarize that instruction?", "對。你會怎麼概括這個指示？"], ["Check the cable first, then follow the startup procedure.", "先檢查電纜，再遵循啟動程序。"]]);
add("g12-s1-u6","基礎題也需核對時間、地點與改期訊息；練習標籤不是分數保證。",[["The invitation says Saturday, but the message says Sunday. Which is right?", "邀請函寫週六，訊息寫週日，到底是哪天？"], ["The message was sent later. It says the event has been moved.", "訊息比較晚寄，上面說活動改期了。"], ["And the location is still the community center?", "地點還是活動中心嗎？"], ["Yes. Only the date changed, so we should keep the original location.", "對。只改日期，所以地點沿用原本的。"]]);
add("g12-s2-u7","口說練習用觀點、理由與例子展開；流利不等於堆疊艱深單字。",[["Would you rather study alone or with a group?", "你比較喜歡自己讀書，還是和小組一起？"], ["Usually alone, because I can work at my own pace.", "通常自己讀，因為可以照自己的步調。"], ["Can you think of a time when a group helped you?", "你想到什麼時候小組對你有幫助嗎？"], ["Yes. Before our science test, explaining ideas to a friend helped me notice gaps.", "有。自然考試前，向朋友解釋概念讓我發現自己沒懂的地方。"]]);
add("g12-s2-u8","商務聽力先核對變更及後續行動；區分原訂時間與更新時間。",[["Has the client confirmed tomorrow's delivery window?", "客戶確認明天的送貨時段了嗎？"], ["Yes. They asked us to arrive after ten because the loading dock is busy earlier.", "確認了。他們請我們十點後到，因為卸貨區之前很忙。"], ["Could you update the driver and send the revised schedule?", "可以通知司機並寄出更新時程嗎？"], ["Will do. I'll ask the client to confirm once they've received it.", "沒問題。我也會請客戶收到後確認。"]]);
add("g12-s2-u9","全英課堂可用 Could you clarify 請求澄清，並用自己的話確認理解。",[["Could you clarify what you mean by a control group?", "可以說明 control group 是什麼意思嗎？"], ["It's the group that doesn't receive the treatment we're testing.", "就是沒有接受我們所測試處置的那一組。"], ["So we compare it with the treatment group to estimate the effect?", "所以我們拿它和處置組比較，估計效果？"], ["That's the idea, provided the groups are comparable in other important ways.", "方向是對的，前提是兩組在其他重要條件上可比較。"]]);
add("g12-s2-u10","批判性思考需區分主張、證據、假設與替代解釋。",[["The author says the new park caused nearby stores to earn more.", "作者說新公園讓附近商店賺更多。"], ["What evidence supports that claim?", "有什麼證據支持這個說法？"], ["Sales rose after the park opened, but a subway station opened nearby, too.", "公園開放後銷售增加，但附近也開了捷運站。"], ["Then we need to consider that alternative explanation before accepting the claim.", "那在接受主張前，我們得考慮那個替代解釋。"]]);
add("g12-s2-u11","整合題需交叉核對文章和圖表；用具體證據解釋排除選項的理由。",[["The chart says attendance fell, but the article says membership grew.", "圖表說出席人數下降，文章卻說會員增加。"], ["Those aren't necessarily the same thing. Members may attend less often.", "兩件事不一定相同，會員可能比較少出席。"], ["So which answer accounts for both sources?", "那哪個答案能同時說明兩份資料？"], ["The one that distinguishes total membership from visits per month.", "區分會員總數和每月到訪次數的那個選項。"]]);
add("g12-s2-u12","持續學習使用小目標、主動回想與回訪安排；紀錄次數不等同精熟。",[["How will you keep practicing English after graduation?", "畢業後你打算怎麼繼續練英文？"], ["I'll listen to a short conversation on my way to work each day.", "我每天上班路上會聽一段短會話。"], ["How will you know whether you're improving?", "你怎麼知道自己有沒有進步？"], ["I'll retell it without the transcript, then review the parts I couldn't explain.", "我會不看逐字稿重述，再複習說不出來的部分。"]]);

export const CHAPTER_DIALOGUE_REVISIONS = {};
function chapter(id,focus,rows) {
 CHAPTER_DIALOGUE_REVISIONS[id] = rows.map(([en,zh],i)=>({speaker:i%2?'Learner':'Mentor',text:en,zh,note:focus}));
}
export function applyChapterDialogueRevisions(tracks) {
 for(const t of tracks)for(const c of t.chapters){const rows=CHAPTER_DIALOGUE_REVISIONS[t.id+':'+c.id];if(rows)c.dialogue=rows.map(l=>({...l}));}
}
chapter("sh:s1","分詞片語常用於書面語；句法選擇服務清晰表達，不代表取得 C1 等級。",[["Can we break this sentence into smaller parts?", "可以把這個句子拆成小部分嗎？"], ["Sure. The main clause is, 'The committee reached a verdict.'", "可以。主要子句是「委員會達成裁決」。"], ["And having reviewed the documents tells us what happened first?", "而 having reviewed the documents 告訴我們什麼先發生？"], ["Exactly. The committee reviewed the documents before reaching its decision.", "對。委員會先審查文件，再作決定。"], ["So the phrase adds background without repeating the subject.", "所以這個片語補充背景，也避免重複主詞。"]]);
chapter("sh:s2","consequences 可為正面或負面；需核對實際指涉，不能只憑字面極性排除。",[["I'm stuck on this sentence-insertion question.", "這題句子插入題我卡住了。"], ["What does these consequences refer to in the option?", "選項裡 these consequences 指什麼？"], ["I'm not sure. The previous paragraph only introduces the experiment.", "我不確定。前一段只介紹實驗。"], ["Then let's check the paragraph that describes its results.", "那我們看看描述結果的段落。"], ["Right. Consequences can be good or bad, so I need the context.", "對。Consequences 可以是好或壞的後果，要看上下文。"]]);
chapter("sh:s4","自然搭配包括 do/conduct research、make a mistake；正式詞不必然比簡單詞好。",[["You wrote make research in this draft. Have you checked that phrase?", "你在草稿寫了 make research，有查過這個搭配嗎？"], ["Not yet. Would do research work better?", "還沒。改成 do research 比較好嗎？"], ["Yes. Conduct research also works, especially in formal writing.", "對。Conduct research 也可以，尤其在正式寫作。"], ["So I should choose the phrase that fits the audience and purpose.", "所以要選適合讀者和目的的說法。"], ["Exactly. Clear, accurate language matters more than fancy words.", "沒錯。清楚準確比華麗用字重要。"]]);
chapter("sh:s5","中譯英先保留意思與主詞關係，避免為艱深而堆疊詞語或製造懸垂修飾。",[["How would you express the idea of exercising regularly to stay healthy?", "你會怎麼表達為了健康而規律運動？"], ["We should exercise regularly to stay healthy.", "We should exercise regularly to stay healthy，為了保持健康，我們應該規律運動。"], ["That's clear. Could you also use a phrase about building a habit?", "很清楚。也能用養成習慣的片語嗎？"], ["We should get into the habit of exercising regularly.", "We should get into the habit of exercising regularly，我們應該養成規律運動的習慣。"], ["Good. Both are natural. Choose the one that fits the surrounding paragraph.", "很好。兩句都自然，選符合前後文的即可。"]]);
chapter("sh:s7","模擬考情境練習檢查答案與時間表達；不以固定分鐘數當成所有考試規則。",[["We have five minutes left. What do you still need to check?", "還有五分鐘，你還要檢查什麼？"], ["I've finished my essay. I'm checking verb tenses and spelling.", "我作文寫完了，正在檢查時態和拼字。"], ["I'm making sure my answers match the numbers on the answer sheet.", "我在確認答案有對準答案卡題號。"], ["Good idea. I skipped a question earlier and came back to it.", "好主意。我前面跳過一題，後來才回來寫。"], ["Let's use the remaining time to check carefully.", "剩下時間就仔細檢查吧。"]]);
chapter("voc:v1","職場防護用語描述場景，不取代現場的風險評估與操作規範。",[["Hold on, Kevin. Do you have your safety glasses and protective footwear?", "等一下，Kevin。你有帶護目鏡、穿防護鞋嗎？"], ["They're in my locker. I was just going to pick up a wrench.", "在置物櫃裡。我本來只是想進去拿扳手。"], ["You still need the required protective equipment before entering this area.", "進這個區域前，仍然要穿戴規定的防護裝備。"], ["Understood. I'll get it before I go in.", "了解。我先拿好再進去。"], ["Thanks. If you're unsure what's required, check with the supervisor.", "謝謝。如果不確定規定，先問領班。"]]);
chapter("voc:v3","緊急停止不等於完成能源隔離；故障時依現場程序並交由授權人員處理。",[["The machine at Station Six has stopped, and I can smell something burning.", "六號工站的機器停了，而且我聞到焦味。"], ["Keep clear of it and alert the supervisor under our emergency procedure.", "先遠離機器，依我們的緊急程序通知領班。"], ["I've reported it. Should I try opening the guard?", "我已經通報了。要試著打開防護罩嗎？"], ["No. An emergency stop doesn't confirm that all energy is isolated.", "不要。按下緊急停止，不代表所有能源都已隔離。"], ["Understood. I'll wait for the authorized maintenance team.", "了解。我等授權維修人員來。"]]);
chapter("voc:v4","圖表與手冊上的數值需以實際設備文件核對；對話不提供通用扭力規格。",[["Which drawing should we use for this pump assembly?", "這組幫浦總成要用哪張圖？"], ["Use the current revision. The old one has a different seal layout.", "用目前版本。舊版的密封件配置不一樣。"], ["Where can I find the bolt torque specification?", "螺栓扭力規格在哪裡？"], ["Check the manufacturer's manual for this exact model.", "查這個確切型號的原廠手冊。"], ["Got it. I'll confirm the model and document revision first.", "了解。我先核對型號和文件版本。"]]);
chapter("voc:v6","摘要保留主旨與關鍵關係；清晰改述不代表保證獲得某個分數。",[["What's the main idea of this article about smart factories?", "這篇智慧工廠文章的主旨是什麼？"], ["Sensors can help maintenance teams spot problems before equipment fails.", "感測器能幫維修團隊在設備故障前發現問題。"], ["Which detail would you keep in a short summary?", "簡短摘要裡你會保留哪個細節？"], ["I'd explain how sensor data helps the team decide when to inspect equipment.", "我會說明感測資料如何幫團隊決定何時檢查設備。"], ["Good. Use your own words, and leave out examples that aren't essential.", "很好。用自己的話說，刪去非必要的例子。"]]);
chapter("intl:gept","用觀點、具體例子與限制自然回答；示範為原創口說練習。",[["How do you use technology when you study English?", "你學英文時怎麼使用科技？"], ["I use an app to review words, and I listen to short conversations on the bus.", "我用應用程式複習單字，在公車上聽短會話。"], ["Is there anything you find less helpful?", "有什麼你覺得比較沒幫助的地方嗎？"], ["Sometimes I rely on translation too much. I try answering in English first.", "有時我太依賴翻譯。我會試著先用英文回答。"], ["Could you give me an example of how you do that?", "可以舉例說明你怎麼做嗎？"]]);
chapter("intl:gre","以轉折與語意線索判斷，不把 although 等連接詞稱為轉折副詞。",[["The senator says her motives are altruistic, but the sentence starts with although.", "參議員說她的動機無私，不過句子以 although 開頭。"], ["So the next clause should contrast with that claim?", "所以下一個子句要和那個說法形成對比？"], ["Yes. Her voting record suggests she acted for her own benefit.", "對。她的投票紀錄顯示她是為自己利益行事。"], ["Then self-interested would fit. Mercenary would suggest a more specific financial motive.", "那 self-interested 合適。Mercenary 會更明確暗示金錢動機。"], ["Exactly. Use the evidence to choose the most precise meaning.", "沒錯。依證據選最精確的意思。"]]);
chapter("intl:toefl","原創學術討論練習；電動化減排與減少壅塞是不同主張，需各自有證據。",[["Should our city help pay for electric buses?", "我們的城市應該補助電動公車嗎？"], ["I think so. They could reduce exhaust emissions along busy routes.", "我認為應該，它們能減少繁忙路線的廢氣排放。"], ["Would switching to electric buses also reduce traffic congestion?", "換電動公車也能減少塞車嗎？"], ["Not by itself. We'd need reliable service that encourages people to leave their cars at home.", "光換車不會，還要有可靠的服務，讓人願意不開車。"], ["Good distinction. What information would help us compare the costs and benefits?", "區分得很好。哪些資訊能幫我們比較成本和效益？"]]);

export const FEATURED_LINE_REVISIONS = {};
function featured(id,index,en,zh,note) {
 (FEATURED_LINE_REVISIONS[id] ||= {})[index]={en,zh,note};
}
export function reviseFeaturedDialogues(dialogues) {
 return dialogues.map(d=>({...d, ...FEATURED_METADATA[d.id], lines:d.lines.map((l,i)=>({...l,...FEATURED_LINE_REVISIONS[d.id]?.[i]}))}));
}
featured("commute-daily-01",2,"Sure thing. Would you like a breakfast sandwich with that?","沒問題。要搭配一份早餐三明治嗎？","a breakfast sandwich 表示一份早餐三明治；with that 表示搭配剛點的飲料。");
featured("commute-daily-01",4,"Of course. Go right ahead. Your coffee will be ready at the pickup counter.","當然，請感應付款。咖啡稍後會在取餐檯備好。","go right ahead 是允許對方操作；pickup counter 是取餐檯。");
featured("commute-daily-02",1,"No, trains on this platform go south. You need Platform One, across the station.","不是，這個月台的車往南。你要去車站另一側的第一月台。","用 trains go south 描述行車方向；確認對方需要的月台。");
featured("commute-daily-03",0,"Hi, I'm here to pick up a package.","你好，我來領包裹。","I'm here to + 動詞，說明來意；package 為常見美式用字。");
featured("commute-daily-03",1,"Sure. What's your last name, and what are the last three digits of your phone number?","好的，請問你貴姓？電話號碼末三碼是什麼？","last three digits 指最後三個數字。");
featured("commute-daily-03",2,"It's eight, two, nine, under the name Chen. I've already paid online. Do you need to see my ID?","末三碼是八、二、九，姓陳。我已經線上付款，需要看證件嗎？","逐位念電話數字；under the name 表登記姓名。");
featured("commute-daily-03",3,"Yes, please. We need to check your photo ID for this pickup. Here's your package.","要，謝謝。這次取件我們需要核對有照片的證件。這是你的包裹。","描述本次店家的取件要求，不推論所有地區都有相同規定。");
featured("commute-daily-04",2,"Yes, please. How long do you think it'll take that way?","好，麻煩了。走那條路大概要多久？","How long do you think it'll take? 是自然詢問所需時間的說法。");
featured("commute-travel-01",0,"Good afternoon. May I see your passport? What's the purpose of your visit?","午安，可以看你的護照嗎？這次來訪的目的是什麼？","入境用語 purpose of your visit；不把海關申報與入境審查混為同一程序。");
featured("commute-travel-02",1,"Welcome, Ms. Wang. Check-in starts at three, and your room isn't quite ready yet.","王女士，歡迎。三點開始入住，你的房間還沒完全準備好。","isn't quite ready yet 表示尚未備妥，語氣比直接說不能入住柔和。");
featured("commute-travel-03",4,"Let me check with the kitchen about the ingredients and possible cross-contact. Would you like separate checks later?","我向廚房確認成分與可能的交叉接觸。稍後你們需要分開結帳嗎？","涉及過敏時先核對，不擅自保證完全不含過敏原；separate checks 為常見美式用語。");
featured("commute-travel-04",2,"The pharmacist can go over the options with you. Are you taking any other medicines?","藥師可以和你討論選項。你有服用其他藥物嗎？","描述諮詢流程，不由會話示範自行指定藥品。");
featured("commute-travel-04",4,"Let's ask the pharmacist about drowsiness and check the label together.","我們問藥師是否會嗜睡，再一起確認標示。","drowsiness 表嗜睡；劑量與使用方式以個別專業指示為準。");
featured("commute-campus-01",3,"Let's finish our parts by Wednesday night so we can rehearse on Thursday.","我們週三晚上前各自完成，週四就能排練。","Let's 比 Let us 更常見於一般口語；so we can 引出目的。");
featured("commute-campus-03",3,"Room B is available from two to four. I've reserved it for you under your student ID.","B 室兩點到四點有空，我用你的學號幫你預約了。","reserve a room 為預約教室；from two to four 表時間範圍。");
featured("commute-work-01",2,"Great. We only have thirty minutes, so let's start with the revised launch timeline.","很好。我們只有三十分鐘，先看更新後的上市時程吧。","let's start with 是自然開會轉入議程的說法。");
featured("commute-work-02",0,"Hi, Marcus. I'm calling about purchase order four oh eight. Port congestion has delayed our shipment by four days.","Marcus 你好。我來電談四〇八號採購單，港口壅塞讓貨延誤四天。","採購單號可逐位念；delay something by four days 表延誤四天。");
featured("commute-work-02",2,"We can send the first two hundred units by air tonight at our expense to keep your line running.","我們今晚可以自費空運前兩百件，讓你們產線繼續運作。","at our expense 表由我方負擔費用；by air 表空運。");
featured("commute-work-03",1,"I understand. How many licenses would you need across your regional offices?","了解。你們各地辦公室總共需要多少授權？","How many licenses would you need? 比 deploy user seats 更適合一般協商口語。");
featured("commute-work-04",1,"Let me check. There's no direct flight tonight, but I can rebook you on a flight through Denver that leaves in fifty minutes.","我查一下。今晚沒有直飛，但可改搭五十分鐘後起飛、經丹佛轉機的航班。","rebook someone on a flight 表替某人改訂航班；取消或停飛原因不能憑空推論。");
featured("commute-esp-01",1,"Stay clear of the equipment. Has the authorized team completed the required energy-isolation procedure?","先遠離設備。授權團隊完成規定的能源隔離程序了嗎？","energy isolation 與 emergency stop 不同，不用單一開關代替完整程序。");
featured("commute-esp-01",2,"Yes. They've confirmed the isolation. I reported dust near the sensor without opening the guard.","完成了，他們確認過隔離。我沒有打開防護罩，已通報感測器附近有灰塵。","report a problem 為通報問題；此處不提供自行檢修步驟。");
featured("commute-esp-01",3,"Thanks. The maintenance team will inspect it and follow the manufacturer's procedure before any restart.","謝謝。維修團隊會檢查，重新啟動前依原廠程序處理。","before any restart 指重新啟動前，作為職場溝通語塊。");
featured("commute-esp-02",1,"Let's check the tool-offset log and inspect the insert before we decide what caused the problem.","先查刀具補正紀錄並檢查刀片，再判斷問題原因。","檢測結果與原因推測要分開，不只憑循環次數斷定磨損原因。");
featured("commute-esp-02",3,"Understood. I'll coordinate with maintenance and submit a new first-article sample for approval.","了解。我會和維修協調，再送新的首件樣品核准。","first-article sample 為首件樣品；for approval 表供核准。");
featured("commute-esp-03",3,"All the tests passed. We're planning a staged rollout at noon, and we'll monitor for errors.","測試全過了。我們計畫中午分階段部署，並監控錯誤。","All the tests passed 比 passed green 自然；不因測試通過便保證零停機。");
featured("commute-esp-04",2,"Check the safety data sheet and our lab procedure for the right gloves and eye protection. Solvent compatibility matters.","依安全資料表與實驗室程序選手套和眼部防護，還要考慮溶劑相容性。","safety data sheet 為安全資料表；不宣稱單一手套材質適用所有化學品。");
featured("commute-esp-04",3,"Understood. I'll check the labeled waste container and confirm the disposal procedure with the supervisor.","了解。我會確認有標示的廢液容器，並向主管核對處理程序。","confirm the procedure with someone 表向某人確認程序。");
featured("commute-intl-02",2,"How do the findings in this practice passage challenge that view?","這篇練習文章的研究結果如何挑戰那個觀點？","明示為原創練習場景，不將未附來源的描述歸於真實研究者。");
featured("commute-intl-02",3,"The passage says some corals exposed to daily temperature swings later tolerated heat better. That suggests the pattern isn't the same everywhere.","文章說某些每天經歷溫度變化的珊瑚後來比較耐熱，顯示並非各地都相同。","some、suggests 限定結論範圍，不把樣本結果擴大為所有珊瑚。");
featured("commute-intl-03",0,"The sentence starts with far from being purely adulatory. Then it says the biography candidly describes the leader's mistakes. What tone would fit the blank?","句子以 far from being purely adulatory 開頭，接著說傳記坦率描述領導者失誤，空格適合什麼語氣？","不讓合成語音念空格符號；far from 表與某種描述相距甚遠。");
featured("commute-intl-03",1,"It needs a word that contrasts with flattering. I'd check whether the choices mean balanced, critical, or unemotional.","需要和吹捧形成對比的字。我會檢查選項是指平衡、批判，還是不帶情緒。","先核對精確語意，不把相近態度詞都當成同義。");
featured("commute-intl-03",2,"Right. Are evenhanded and dispassionate exact synonyms?","對。Evenhanded 和 dispassionate 是完全相同的意思嗎？","evenhanded 強調公平平衡；dispassionate 強調不受情緒左右。");
featured("commute-intl-03",3,"Not exactly. Evenhanded means fair and balanced; dispassionate means not influenced by emotion. We need the full sentence and all the choices.","不完全。Evenhanded 指公平平衡；dispassionate 指不受情緒影響。需要完整句子和所有選項才能判斷。","句子等價題還需確認兩個完整句子是否表達相近意思。");
featured("commute-intl-04",3,"Exactly. We'd need a suitable comparison and more evidence to separate those effects. That would make the causal claim more credible.","對。我們需要適當比較和更多證據，分辨各種因素的影響，因果主張才更可信。","單一比較本身不保證識別因果，仍須考慮群體差異等因素。");
chapter("jhs:j1","時態依說話當下、日常習慣及明確過去時間選擇；口語縮寫不改變時態。",[["Hey, Beth. Are you still working on your homework?", "Beth，你還在寫作業嗎？"], ["Yes, I'm finishing the last question. Did you finish yours yesterday?", "對，還在寫最後一題。你昨天寫完了嗎？"], ["I did. I usually do it before dinner.", "寫完了，我通常晚餐前做。"], ["I should try that. Let's review the science notes after class.", "我也該試試。下課後一起複習自然筆記吧。"]]);
chapter("jhs:j2","a few 配可數複數；a little 配不可數名詞；代名詞需有清楚指涉。",[["Do we have any bread left?", "我們還有麵包嗎？"], ["Just a little, but there's some cheese in the fridge.", "只剩一點，不過冰箱裡有些起司。"], ["I'll get a few rolls. Do you need anything else?", "我去買幾個小餐包，還需要什麼嗎？"], ["Some apples, please. Here's ten dollars for the groceries.", "麻煩帶一些蘋果，這十元拿去買食物。"]]);
chapter("jhs:j3","邀約可用 Would you like to；詢問安排用 Where and when should we meet?",[["Would you like to see a movie this Saturday?", "週六想去看電影嗎？"], ["I'd love to. Which one do you have in mind?", "很想。你想看哪一部？"], ["How about the new space movie? We could meet at two.", "那部新的太空電影如何？我們可以兩點見面。"], ["Sounds good. Let's meet by the ticket counter.", "好，就在售票處旁邊碰面。"]]);
chapter("jhs:j4","although 表讓步，unless 表除非，so that 表目的；依實際條件建立前後關係。",[["Although the forecast said it would be sunny, those clouds look pretty dark.", "雖然預報說晴天，那些雲看起來很暗。"], ["Should we move the picnic indoors if it rains?", "下雨的話，要把野餐移到室內嗎？"], ["Yes. Unless the weather clears up, let's use the community room.", "要。除非天氣轉好，不然用活動室吧。"], ["I'll cover the food so that it doesn't get wet on the way.", "我把食物蓋好，路上才不會淋濕。"]]);
chapter("jhs:j5","公告資訊要核對日期、折扣門檻與條件；百分之三十折扣為支付原價百分之七十。",[["Does the museum offer a group discount?", "博物館有團體優惠嗎？"], ["Yes. Groups of ten or more get thirty percent off.", "有，十人以上打七折。"], ["We have twelve students. Do we need to book ahead?", "我們有十二位學生，需要先預約嗎？"], ["The notice says we do. Let's call before we go.", "公告說要，我們出發前先打電話。"]]);
chapter("jhs:j6","thirteen、thirty 的節奏與重音受句子強調影響；可用數字分位確認。",[["Hi, could I get a latte and two muffins, please?", "你好，請給我一杯拿鐵和兩個瑪芬。"], ["Sure. That comes to thirteen dollars and fifty cents.", "好，總共十三元五角。"], ["Sorry, was that thirteen or thirty?", "不好意思，是十三還是三十？"], ["Thirteen. One three, and fifty cents.", "十三，一、三，再加五角。"]]);
chapter("jhs:j7","訂正區分時間不足、字詞與理解問題；以證據與新題確認而非只背答案。",[["You got forty out of forty-three on this practice test. What felt difficult?", "這份練習你答對四十三題中的四十題，哪裡覺得困難？"], ["I spent too long on one question and rushed the last passage.", "我在一題花太久，最後一篇讀得很匆忙。"], ["Let's review that question, then try setting a time limit for each section.", "先檢查那題，再試著替每部分設時間上限。"], ["Good idea. I also want to explain why the other choices are wrong.", "好主意，我也想說明其他選項為什麼不對。"]]);
chapter("sh:s3","比較文本需保留各作者主張與限制；避免把文本例子說成普遍事實。",[["Text A says remote work improves productivity. How does Text B respond?", "A 文說遠距工作提升生產力，B 文怎麼回應？"], ["It points out that new employees may miss informal advice from coworkers.", "它指出新員工可能少了同事的非正式指導。"], ["So is Text B rejecting remote work entirely?", "所以 B 文完全反對遠距工作嗎？"], ["No. It's questioning whether short-term output tells the whole story.", "不是，它質疑短期產出能否說明全貌。"]]);
chapter("sh:s6","主旨句需提出可展開的具體主張；不把寬泛預測與高分公式混同。",[["Your opening gets my attention, but what's the main claim?", "你的開頭吸引我了，但主要主張是什麼？"], ["I wrote that AI will change education. Is that too broad?", "我寫 AI 會改變教育，這樣太廣嗎？"], ["A little. What role do you think AI should play in the classroom?", "有一點。你認為 AI 在教室應扮演什麼角色？"], ["It should support feedback, while teachers guide discussion and help students evaluate ideas.", "它應輔助回饋，由老師引導討論、幫學生評估想法。"]]);
chapter("voc:v2","量測先核對單位和允收範圍；對話數值為練習例子，不取代實際圖面。",[["What reading did you get for sample four?", "四號樣品的讀數是多少？"], ["Twenty-five point zero four millimeters.", "二十五點〇四毫米。"], ["The drawing allows twenty-four point nine eight to twenty-five point zero two.", "圖面允收範圍是二十四點九八到二十五點〇二。"], ["Then this sample is above the upper limit. I'll record it and notify quality control.", "那這個樣品超過上限，我會記錄並通知品管。"]]);
chapter("voc:v5","電話自報公司；confirm the shipping date 核對出貨日，尚未出貨不當成已抵達。",[["Hi, this is Mr. Lin from Taiwan Precision Machinery. I'm calling about our order.", "你好，我是台灣精密機械的林先生，想詢問訂單。"], ["Of course. Do you have the purchase order number?", "好的，有採購單號嗎？"], ["Yes, it's five one six. Could you confirm when the servo drives will ship?", "有，是五一六。可以確認伺服驅動器何時出貨嗎？"], ["They're scheduled to ship Thursday. I'll email the tracking details once they're available.", "預定週四出貨，有追蹤資料後我會寄給你。"]]);
chapter("voc:v7","驗收會議區分實際測試結果、未完成事項與簽核條件，不以一句全過概括所有風險。",[["Before we sign off, are there any open issues from the acceptance test?", "簽核前，驗收測試還有待處理事項嗎？"], ["One label needs updating. The test results are attached to the report.", "一個標籤需要更新，測試結果已附在報告。"], ["Can you send the revised label and confirm who will approve the change?", "能寄更新後標籤，並確認誰核准變更嗎？"], ["Yes. I'll send both today so we can complete the review.", "可以，今天會一起寄出，讓我們完成審查。"]]);
chapter("intl:toeic","invoice 與 reimbursement 的情境需區分：公司採購付款可送會計部處理，不必然為個人報銷。",[["Has the supplier confirmed delivery of the packaging materials?", "供應商確認包材交貨了嗎？"], ["Yes. They expect everything to arrive by next Wednesday.", "確認了，他們預計下週三前全部到。"], ["Please send the updated invoice to accounting and keep me posted on any delays.", "把更新發票送會計部，有延誤隨時通知我。"], ["Will do. I'll also check the tracking details tomorrow morning.", "沒問題，明早我也會查追蹤資料。"]]);
chapter("intl:sat","原創閱讀練習需依文本證據推論，不聲稱是官方特定模組題號。",[["Why did you choose C in this reading practice?", "這題閱讀練習你為什麼選 C？"], ["The passage says the new samples don't support the earlier explanation.", "文章說新樣本不支持原先的解釋。"], ["So which word in C matches that relationship?", "所以 C 裡哪個字對應這個關係？"], ["Undermine. The findings weaken the explanation, even if they don't completely disprove it.", "Undermine。研究結果削弱那個解釋，即使未完全推翻。"]]);
chapter("intl:gmat","區分需求、收入與淨利；增加銷量不保證淨利上升，需補充條件與證據。",[["The client expects a price cut to increase both market share and profit.", "客戶預期降價能同時提高市占率和利潤。"], ["What would have to be true for profit to rise?", "要讓利潤增加，需要哪些條件成立？"], ["Extra sales would need to make up for the lower margin and any added costs.", "新增銷售必須彌補較低利潤率和增加的成本。"], ["We should also ask how competitors might respond before accepting that forecast.", "接受預測前，也應詢問競爭對手可能如何回應。"]]);
featured("commute-campus-02",3,"That's a good focus. In paragraph two, try backing up your claim with a concrete example.","這個焦點不錯。第二段試著用具體例子支持你的主張。","back up a claim with evidence 表用證據支持主張。");
